{
  "name": "scalable-shopping-cart",
  "version": "1.0.0",
  "description": "Arquitectura modular y escalable para un carrito de la compra en TypeScript",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "tsc && node --test tests/*.test.mjs",
    "demo": "tsc && node examples/demo.mjs"
  },
  "engines": {
    "node": ">=20.0.0"
  }
}

export class DomainError extends Error {
  public readonly code: string;
  public readonly details?: Record<string, unknown>;

  constructor(code: string, message: string, details?: Record<string, unknown>) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    if (details !== undefined) {
      this.details = details;
    }
  }
}

export class CartNotFoundError extends DomainError {
  constructor(cartId: string) {
    super('CART_NOT_FOUND', `El carrito "${cartId}" no existe.`, { cartId });
  }
}

export class CartInactiveError extends DomainError {
  constructor(cartId: string, status: string) {
    super(
      'CART_INACTIVE',
      `El carrito "${cartId}" no puede modificarse porque su estado es "${status}".`,
      { cartId, status },
    );
  }
}

export class ConcurrencyConflictError extends DomainError {
  constructor(cartId: string, expectedVersion: number, actualVersion: number) {
    super(
      'CONCURRENCY_CONFLICT',
      `Conflicto de concurrencia en carrito "${cartId}": se esperaba versión ${expectedVersion}, pero la actual es ${actualVersion}.`,
      { cartId, expectedVersion, actualVersion },
    );
  }
}

export class InvalidCurrencyError extends DomainError {
  constructor(expected: string, actual: string) {
    super(
      'INVALID_CURRENCY',
      `Moneda incompatible: se esperaba "${expected}", se recibió "${actual}".`,
      { expected, actual },
    );
  }
}

export class InvalidQuantityError extends DomainError {
  constructor(quantity: number, reason = 'La cantidad debe ser un entero positivo.') {
    super('INVALID_QUANTITY', `${reason} Valor recibido: ${quantity}.`, { quantity });
  }
}

export class InsufficientStockError extends DomainError {
  constructor(productId: string, requested: number, available: number) {
    super(
      'INSUFFICIENT_STOCK',
      `Stock insuficiente para el producto "${productId}": solicitado ${requested}, disponible ${available}.`,
      { productId, requested, available },
    );
  }
}

export class CatalogItemNotFoundError extends DomainError {
  constructor(productId: string) {
    super('CATALOG_ITEM_NOT_FOUND', `Producto "${productId}" no encontrado en el catálogo.`, {
      productId,
    });
  }
}

export class PromotionError extends DomainError {
  constructor(code: string, message: string, details?: Record<string, unknown>) {
    super(code, message, details);
  }
}

import { DomainError, InvalidCurrencyError } from './errors.js';

export type CurrencyCode = string;

export interface MoneyJSON {
  amountMinor: number;
  currency: CurrencyCode;
}

/**
 * Value Object inmutable para importes monetarios.
 * Almacena las cantidades en unidades mínimas enteras (p. ej. céntimos)
 * para evitar errores de redondeo en coma flotante.
 */
export class Money {
  public readonly amountMinor: number;
  public readonly currency: CurrencyCode;

  private constructor(amountMinor: number, currency: CurrencyCode) {
    if (!Number.isSafeInteger(amountMinor)) {
      throw new DomainError(
        'INVALID_MONEY_AMOUNT',
        `El importe en unidades mínimas debe ser un entero seguro. Recibido: ${amountMinor}`,
      );
    }
    const normalized = currency.trim().toUpperCase();
    if (!/^[A-Z]{3}$/.test(normalized)) {
      throw new DomainError(
        'INVALID_CURRENCY_CODE',
        `El código de moneda debe seguir ISO-4217 (3 letras). Recibido: "${currency}"`,
      );
    }
    this.amountMinor = amountMinor;
    this.currency = normalized;
  }

  public static fromMinor(amountMinor: number, currency: CurrencyCode): Money {
    return new Money(amountMinor, currency);
  }

  public static fromMajor(amountMajor: number, currency: CurrencyCode, decimals = 2): Money {
    if (!Number.isFinite(amountMajor)) {
      throw new DomainError('INVALID_MONEY_AMOUNT', `Importe no válido: ${amountMajor}`);
    }
    const factor = 10 ** decimals;
    return new Money(Math.round(amountMajor * factor), currency);
  }

  public static zero(currency: CurrencyCode): Money {
    return new Money(0, currency);
  }

  public static fromJSON(json: MoneyJSON): Money {
    return new Money(json.amountMinor, json.currency);
  }

  public isZero(): boolean {
    return this.amountMinor === 0;
  }

  public isNegative(): boolean {
    return this.amountMinor < 0;
  }

  public isPositive(): boolean {
    return this.amountMinor > 0;
  }

  public assertSameCurrency(other: Money): void {
    if (this.currency !== other.currency) {
      throw new InvalidCurrencyError(this.currency, other.currency);
    }
  }

  public add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amountMinor + other.amountMinor, this.currency);
  }

  public subtract(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amountMinor - other.amountMinor, this.currency);
  }

  /**
   * Resta asegurando un mínimo de 0 (útil para descuentos).
   */
  public subtractClampedZero(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(Math.max(0, this.amountMinor - other.amountMinor), this.currency);
  }

  public multiply(factor: number): Money {
    if (!Number.isFinite(factor)) {
      throw new DomainError('INVALID_MULTIPLIER', `Factor no válido: ${factor}`);
    }
    return new Money(Math.round(this.amountMinor * factor), this.currency);
  }

  public percentage(percent: number): Money {
    if (!Number.isFinite(percent) || percent < 0) {
      throw new DomainError('INVALID_PERCENTAGE', `Porcentaje no válido: ${percent}`);
    }
    return new Money(Math.round((this.amountMinor * percent) / 100), this.currency);
  }

  public min(other: Money): Money {
    this.assertSameCurrency(other);
    return this.amountMinor <= other.amountMinor ? this : other;
  }

  public max(other: Money): Money {
    this.assertSameCurrency(other);
    return this.amountMinor >= other.amountMinor ? this : other;
  }

  public equals(other: Money): boolean {
    return this.currency === other.currency && this.amountMinor === other.amountMinor;
  }

  public greaterThan(other: Money): boolean {
    this.assertSameCurrency(other);
    return this.amountMinor > other.amountMinor;
  }

  public greaterThanOrEqual(other: Money): boolean {
    this.assertSameCurrency(other);
    return this.amountMinor >= other.amountMinor;
  }

  public lessThan(other: Money): boolean {
    this.assertSameCurrency(other);
    return this.amountMinor < other.amountMinor;
  }

  public toMajor(decimals = 2): number {
    return this.amountMinor / 10 ** decimals;
  }

  public format(locale = 'es-ES', decimals = 2): string {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: this.currency,
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }).format(this.toMajor(decimals));
  }

  public toJSON(): MoneyJSON {
    return {
      amountMinor: this.amountMinor,
      currency: this.currency,
    };
  }
}

export interface DomainEvent<TType extends string = string, TPayload = Record<string, unknown>> {
  readonly eventId: string;
  readonly type: TType;
  readonly aggregateId: string;
  readonly occurredAt: string;
  readonly version: number;
  readonly payload: TPayload;
}

export type CartEvent =
  | DomainEvent<'CartCreated', { ownerId: string | null; currency: string }>
  | DomainEvent<
      'CartItemAdded',
      { lineKey: string; productId: string; quantity: number; unitPriceMinor: number }
    >
  | DomainEvent<
      'CartItemQuantityUpdated',
      { lineKey: string; productId: string; previousQuantity: number; newQuantity: number }
    >
  | DomainEvent<'CartItemRemoved', { lineKey: string; productId: string }>
  | DomainEvent<'CartCleared', { removedCount: number }>
  | DomainEvent<'CartCouponApplied', { code: string }>
  | DomainEvent<'CartCouponRemoved', { code: string }>
  | DomainEvent<'CartMerged', { sourceCartId: string; mergedItemsCount: number }>
  | DomainEvent<'CartCheckedOut', { ownerId: string | null; itemCount: number }>;

let eventCounter = 0;

export function createDomainEvent<TType extends CartEvent['type']>(
  type: TType,
  aggregateId: string,
  version: number,
  payload: Extract<CartEvent, { type: TType }>['payload'],
  now: Date = new Date(),
): Extract<CartEvent, { type: TType }> {
  eventCounter += 1;
  const randomPart = Math.random().toString(36).slice(2, 10);
  return {
    eventId: `evt_${now.getTime()}_${eventCounter}_${randomPart}`,
    type,
    aggregateId,
    occurredAt: now.toISOString(),
    version,
    payload,
  } as Extract<CartEvent, { type: TType }>;
}

import { InvalidQuantityError } from './errors.js';
import { Money, type MoneyJSON } from './money.js';

export type TaxCategory = 'STANDARD' | 'REDUCED' | 'SUPER_REDUCED' | 'EXEMPT';

export interface CartItemProps {
  productId: string;
  variantId?: string;
  sku: string;
  name: string;
  categoryId: string;
  taxCategory: TaxCategory;
  unitPrice: Money;
  quantity: number;
  weightGrams?: number;
  metadata?: Record<string, string | number | boolean>;
}

export interface CartItemSnapshot {
  lineKey: string;
  productId: string;
  variantId?: string;
  sku: string;
  name: string;
  categoryId: string;
  taxCategory: TaxCategory;
  unitPrice: MoneyJSON;
  quantity: number;
  weightGrams?: number;
  metadata?: Record<string, string | number | boolean>;
}

export function buildLineKey(productId: string, variantId?: string): string {
  return variantId ? `${productId}::${variantId}` : productId;
}

export function assertValidQuantity(quantity: number, maxQuantity = 10_000): void {
  if (!Number.isSafeInteger(quantity) || quantity <= 0) {
    throw new InvalidQuantityError(quantity);
  }
  if (quantity > maxQuantity) {
    throw new InvalidQuantityError(
      quantity,
      `La cantidad supera el límite máximo permitido (${maxQuantity}).`,
    );
  }
}

export class CartItem {
  public readonly lineKey: string;
  public readonly productId: string;
  public readonly variantId?: string;
  public readonly sku: string;
  public readonly name: string;
  public readonly categoryId: string;
  public readonly taxCategory: TaxCategory;
  public readonly unitPrice: Money;
  public readonly quantity: number;
  public readonly weightGrams: number;
  public readonly metadata: Record<string, string | number | boolean>;

  constructor(props: CartItemProps) {
    assertValidQuantity(props.quantity);
    this.productId = props.productId;
    if (props.variantId !== undefined) {
      this.variantId = props.variantId;
    }
    this.lineKey = buildLineKey(props.productId, props.variantId);
    this.sku = props.sku;
    this.name = props.name;
    this.categoryId = props.categoryId;
    this.taxCategory = props.taxCategory;
    this.unitPrice = props.unitPrice;
    this.quantity = props.quantity;
    this.weightGrams = props.weightGrams ?? 0;
    this.metadata = props.metadata ? { ...props.metadata } : {};
  }

  public subtotal(): Money {
    return this.unitPrice.multiply(this.quantity);
  }

  public totalWeightGrams(): number {
    return this.weightGrams * this.quantity;
  }

  public withQuantity(newQuantity: number, maxQuantity = 10_000): CartItem {
    assertValidQuantity(newQuantity, maxQuantity);
    return new CartItem({
      productId: this.productId,
      ...(this.variantId !== undefined ? { variantId: this.variantId } : {}),
      sku: this.sku,
      name: this.name,
      categoryId: this.categoryId,
      taxCategory: this.taxCategory,
      unitPrice: this.unitPrice,
      quantity: newQuantity,
      weightGrams: this.weightGrams,
      metadata: this.metadata,
    });
  }

  public withUnitPrice(newUnitPrice: Money): CartItem {
    this.unitPrice.assertSameCurrency(newUnitPrice);
    return new CartItem({
      productId: this.productId,
      ...(this.variantId !== undefined ? { variantId: this.variantId } : {}),
      sku: this.sku,
      name: this.name,
      categoryId: this.categoryId,
      taxCategory: this.taxCategory,
      unitPrice: newUnitPrice,
      quantity: this.quantity,
      weightGrams: this.weightGrams,
      metadata: this.metadata,
    });
  }

  public toSnapshot(): CartItemSnapshot {
    return {
      lineKey: this.lineKey,
      productId: this.productId,
      ...(this.variantId !== undefined ? { variantId: this.variantId } : {}),
      sku: this.sku,
      name: this.name,
      categoryId: this.categoryId,
      taxCategory: this.taxCategory,
      unitPrice: this.unitPrice.toJSON(),
      quantity: this.quantity,
      weightGrams: this.weightGrams,
      metadata: { ...this.metadata },
    };
  }

  public static fromSnapshot(snapshot: CartItemSnapshot): CartItem {
    return new CartItem({
      productId: snapshot.productId,
      ...(snapshot.variantId !== undefined ? { variantId: snapshot.variantId } : {}),
      sku: snapshot.sku,
      name: snapshot.name,
      categoryId: snapshot.categoryId,
      taxCategory: snapshot.taxCategory,
      unitPrice: Money.fromJSON(snapshot.unitPrice),
      quantity: snapshot.quantity,
      ...(snapshot.weightGrams !== undefined ? { weightGrams: snapshot.weightGrams } : {}),
      ...(snapshot.metadata !== undefined ? { metadata: snapshot.metadata } : {}),
    });
  }
}

import {
  buildLineKey,
  CartItem,
  type CartItemProps,
  type CartItemSnapshot,
} from './cart-item.js';
import { CartInactiveError, DomainError } from './errors.js';
import { createDomainEvent, type CartEvent } from './events.js';
import { Money, type CurrencyCode } from './money.js';

export type CartStatus = 'ACTIVE' | 'CHECKED_OUT' | 'EXPIRED' | 'MERGED';

export interface CartLimits {
  maxLineItems: number;
  maxQuantityPerLine: number;
}

export interface CreateCartOptions {
  id: string;
  ownerId?: string | null;
  currency: CurrencyCode;
  ttlMs?: number | null;
  limits?: Partial<CartLimits>;
  now?: Date;
}

export interface CartSnapshot {
  id: string;
  ownerId: string | null;
  currency: CurrencyCode;
  status: CartStatus;
  version: number;
  items: CartItemSnapshot[];
  couponCodes: string[];
  createdAt: string;
  updatedAt: string;
  expiresAt: string | null;
  limits: CartLimits;
}

const DEFAULT_LIMITS: CartLimits = {
  maxLineItems: 500,
  maxQuantityPerLine: 999,
};

/**
 * Aggregate Root: Cart
 * Encapsula invariantes de negocio, control de concurrencia optimista (`version`)
 * y emisión de eventos de dominio.
 */
export class Cart {
  public readonly id: string;
  private _ownerId: string | null;
  public readonly currency: CurrencyCode;
  private _status: CartStatus;
  private _version: number;
  private readonly _items: Map<string, CartItem>;
  private readonly _couponCodes: Set<string>;
  public readonly createdAt: Date;
  private _updatedAt: Date;
  private _expiresAt: Date | null;
  public readonly limits: CartLimits;
  private _domainEvents: CartEvent[] = [];

  private constructor(params: {
    id: string;
    ownerId: string | null;
    currency: CurrencyCode;
    status: CartStatus;
    version: number;
    items: Map<string, CartItem>;
    couponCodes: Set<string>;
    createdAt: Date;
    updatedAt: Date;
    expiresAt: Date | null;
    limits: CartLimits;
  }) {
    this.id = params.id;
    this._ownerId = params.ownerId;
    this.currency = params.currency.trim().toUpperCase();
    this._status = params.status;
    this._version = params.version;
    this._items = params.items;
    this._couponCodes = params.couponCodes;
    this.createdAt = params.createdAt;
    this._updatedAt = params.updatedAt;
    this._expiresAt = params.expiresAt;
    this.limits = params.limits;
  }

  public static create(options: CreateCartOptions): Cart {
    const now = options.now ?? new Date();
    const limits: CartLimits = {
      maxLineItems: options.limits?.maxLineItems ?? DEFAULT_LIMITS.maxLineItems,
      maxQuantityPerLine:
        options.limits?.maxQuantityPerLine ?? DEFAULT_LIMITS.maxQuantityPerLine,
    };
    const expiresAt =
      options.ttlMs !== undefined && options.ttlMs !== null
        ? new Date(now.getTime() + options.ttlMs)
        : null;

    const cart = new Cart({
      id: options.id,
      ownerId: options.ownerId ?? null,
      currency: Money.zero(options.currency).currency,
      status: 'ACTIVE',
      version: 1,
      items: new Map(),
      couponCodes: new Set(),
      createdAt: now,
      updatedAt: now,
      expiresAt,
      limits,
    });

    cart._domainEvents.push(
      createDomainEvent(
        'CartCreated',
        cart.id,
        cart._version,
        { ownerId: cart._ownerId, currency: cart.currency },
        now,
      ),
    );
    return cart;
  }

  public static fromSnapshot(snapshot: CartSnapshot): Cart {
    const items = new Map<string, CartItem>();
    for (const itemSnap of snapshot.items) {
      const item = CartItem.fromSnapshot(itemSnap);
      items.set(item.lineKey, item);
    }

    return new Cart({
      id: snapshot.id,
      ownerId: snapshot.ownerId,
      currency: snapshot.currency,
      status: snapshot.status,
      version: snapshot.version,
      items,
      couponCodes: new Set(snapshot.couponCodes),
      createdAt: new Date(snapshot.createdAt),
      updatedAt: new Date(snapshot.updatedAt),
      expiresAt: snapshot.expiresAt ? new Date(snapshot.expiresAt) : null,
      limits: { ...snapshot.limits },
    });
  }

  public get ownerId(): string | null {
    return this._ownerId;
  }

  public get status(): CartStatus {
    return this._status;
  }

  public get version(): number {
    return this._version;
  }

  public get updatedAt(): Date {
    return this._updatedAt;
  }

  public get expiresAt(): Date | null {
    return this._expiresAt;
  }

  public get items(): ReadonlyArray<CartItem> {
    return Array.from(this._items.values());
  }

  public get couponCodes(): ReadonlyArray<string> {
    return Array.from(this._couponCodes);
  }

  public get lineCount(): number {
    return this._items.size;
  }

  public get totalQuantity(): number {
    let total = 0;
    for (const item of this._items.values()) {
      total += item.quantity;
    }
    return total;
  }

  public isEmpty(): boolean {
    return this._items.size === 0;
  }

  public isExpired(now: Date = new Date()): boolean {
    if (this._status === 'EXPIRED') return true;
    if (this._expiresAt !== null && now.getTime() >= this._expiresAt.getTime()) {
      return true;
    }
    return false;
  }

  public getItem(productId: string, variantId?: string): CartItem | undefined {
    return this._items.get(buildLineKey(productId, variantId));
  }

  public getItemByLineKey(lineKey: string): CartItem | undefined {
    return this._items.get(lineKey);
  }

  public subtotal(): Money {
    let acc = Money.zero(this.currency);
    for (const item of this._items.values()) {
      acc = acc.add(item.subtotal());
    }
    return acc;
  }

  public totalWeightGrams(): number {
    let total = 0;
    for (const item of this._items.values()) {
      total += item.totalWeightGrams();
    }
    return total;
  }

  private assertActive(now: Date = new Date()): void {
    if (this._status !== 'ACTIVE') {
      throw new CartInactiveError(this.id, this._status);
    }
    if (this.isExpired(now)) {
      this._status = 'EXPIRED';
      throw new CartInactiveError(this.id, 'EXPIRED');
    }
  }

  private touch(now: Date, extendTtlMs?: number): void {
    this._version += 1;
    this._updatedAt = now;
    if (extendTtlMs !== undefined) {
      this._expiresAt = new Date(now.getTime() + extendTtlMs);
    }
  }

  public addItem(
    props: CartItemProps,
    options?: { now?: Date; extendTtlMs?: number },
  ): CartItem {
    const now = options?.now ?? new Date();
    this.assertActive(now);

    if (props.unitPrice.currency !== this.currency) {
      Money.zero(this.currency).assertSameCurrency(props.unitPrice);
    }

    const lineKey = buildLineKey(props.productId, props.variantId);
    const existing = this._items.get(lineKey);

    if (existing) {
      const nextQuantity = existing.quantity + props.quantity;
      const updated = new CartItem({
        ...props,
        quantity: nextQuantity,
      }).withQuantity(nextQuantity, this.limits.maxQuantityPerLine);

      this._items.set(lineKey, updated);
      this.touch(now, options?.extendTtlMs);
      this._domainEvents.push(
        createDomainEvent(
          'CartItemQuantityUpdated',
          this.id,
          this._version,
          {
            lineKey,
            productId: props.productId,
            previousQuantity: existing.quantity,
            newQuantity: nextQuantity,
          },
          now,
        ),
      );
      return updated;
    }

    if (this._items.size >= this.limits.maxLineItems) {
      throw new DomainError(
        'MAX_CART_LINES_EXCEEDED',
        `El carrito no puede superar ${this.limits.maxLineItems} líneas distintas.`,
        { maxLineItems: this.limits.maxLineItems },
      );
    }

    const item = new CartItem(props).withQuantity(
      props.quantity,
      this.limits.maxQuantityPerLine,
    );
    this._items.set(lineKey, item);
    this.touch(now, options?.extendTtlMs);
    this._domainEvents.push(
      createDomainEvent(
        'CartItemAdded',
        this.id,
        this._version,
        {
          lineKey,
          productId: item.productId,
          quantity: item.quantity,
          unitPriceMinor: item.unitPrice.amountMinor,
        },
        now,
      ),
    );
    return item;
  }

  public updateItemQuantity(
    lineKey: string,
    newQuantity: number,
    options?: { now?: Date; extendTtlMs?: number },
  ): CartItem | null {
    const now = options?.now ?? new Date();
    this.assertActive(now);

    const existing = this._items.get(lineKey);
    if (!existing) {
      throw new DomainError(
        'CART_ITEM_NOT_FOUND',
        `La línea "${lineKey}" no existe en el carrito "${this.id}".`,
        { cartId: this.id, lineKey },
      );
    }

    if (newQuantity === 0) {
      this._items.delete(lineKey);
      this.touch(now, options?.extendTtlMs);
      this._domainEvents.push(
        createDomainEvent(
          'CartItemRemoved',
          this.id,
          this._version,
          { lineKey, productId: existing.productId },
          now,
        ),
      );
      return null;
    }

    const updated = existing.withQuantity(newQuantity, this.limits.maxQuantityPerLine);
    this._items.set(lineKey, updated);
    this.touch(now, options?.extendTtlMs);
    this._domainEvents.push(
      createDomainEvent(
        'CartItemQuantityUpdated',
        this.id,
        this._version,
        {
          lineKey,
          productId: existing.productId,
          previousQuantity: existing.quantity,
          newQuantity,
        },
        now,
      ),
    );
    return updated;
  }

  public removeItem(
    lineKey: string,
    options?: { now?: Date; extendTtlMs?: number },
  ): boolean {
    const now = options?.now ?? new Date();
    this.assertActive(now);

    const existing = this._items.get(lineKey);
    if (!existing) {
      return false;
    }
    this._items.delete(lineKey);
    this.touch(now, options?.extendTtlMs);
    this._domainEvents.push(
      createDomainEvent(
        'CartItemRemoved',
        this.id,
        this._version,
        { lineKey, productId: existing.productId },
        now,
      ),
    );
    return true;
  }

  public clear(options?: { now?: Date }): void {
    const now = options?.now ?? new Date();
    this.assertActive(now);

    const removedCount = this._items.size;
    if (removedCount === 0 && this._couponCodes.size === 0) {
      return;
    }
    this._items.clear();
    this._couponCodes.clear();
    this.touch(now);
    this._domainEvents.push(
      createDomainEvent('CartCleared', this.id, this._version, { removedCount }, now),
    );
  }

  public applyCoupon(code: string, options?: { now?: Date }): boolean {
    const now = options?.now ?? new Date();
    this.assertActive(now);

    const normalized = code.trim().toUpperCase();
    if (!normalized) {
      throw new DomainError('INVALID_COUPON_CODE', 'El código de cupón no puede estar vacío.');
    }
    if (this._couponCodes.has(normalized)) {
      return false;
    }
    this._couponCodes.add(normalized);
    this.touch(now);
    this._domainEvents.push(
      createDomainEvent(
        'CartCouponApplied',
        this.id,
        this._version,
        { code: normalized },
        now,
      ),
    );
    return true;
  }

  public removeCoupon(code: string, options?: { now?: Date }): boolean {
    const now = options?.now ?? new Date();
    this.assertActive(now);

    const normalized = code.trim().toUpperCase();
    const deleted = this._couponCodes.delete(normalized);
    if (!deleted) return false;
    this.touch(now);
    this._domainEvents.push(
      createDomainEvent(
        'CartCouponRemoved',
        this.id,
        this._version,
        { code: normalized },
        now,
      ),
    );
    return true;
  }

  public assignOwner(ownerId: string, now: Date = new Date()): void {
    this.assertActive(now);
    this._ownerId = ownerId;
    this.touch(now);
  }

  /**
   * Fusiona los ítems y cupones de otro carrito (por ejemplo, de sesión invitada)
   * dentro de este carrito, marcando el carrito origen como MERGED.
   */
  public mergeFrom(source: Cart, now: Date = new Date()): number {
    this.assertActive(now);
    source.assertActive(now);

    if (this.id === source.id) {
      throw new DomainError('SELF_MERGE', 'No se puede fusionar un carrito consigo mismo.');
    }
    if (this.currency !== source.currency) {
      Money.zero(this.currency).assertSameCurrency(Money.zero(source.currency));
    }

    let mergedCount = 0;
    for (const incoming of source.items) {
      const existing = this._items.get(incoming.lineKey);
      if (existing) {
        const combined = Math.min(
          existing.quantity + incoming.quantity,
          this.limits.maxQuantityPerLine,
        );
        this._items.set(
          incoming.lineKey,
          incoming.withQuantity(combined, this.limits.maxQuantityPerLine),
        );
        mergedCount += 1;
      } else {
        if (this._items.size >= this.limits.maxLineItems) {
          break;
        }
        const boundedQty = Math.min(incoming.quantity, this.limits.maxQuantityPerLine);
        this._items.set(
          incoming.lineKey,
          incoming.withQuantity(boundedQty, this.limits.maxQuantityPerLine),
        );
        mergedCount += 1;
      }
    }

    for (const code of source.couponCodes) {
      this._couponCodes.add(code);
    }

    source._status = 'MERGED';
    source.touch(now);
    this.touch(now);

    this._domainEvents.push(
      createDomainEvent(
        'CartMerged',
        this.id,
        this._version,
        { sourceCartId: source.id, mergedItemsCount: mergedCount },
        now,
      ),
    );
    return mergedCount;
  }

  public markCheckedOut(now: Date = new Date()): void {
    this.assertActive(now);
    if (this._items.size === 0) {
      throw new DomainError(
        'EMPTY_CART_CHECKOUT',
        `No se puede finalizar la compra de un carrito vacío ("${this.id}").`,
      );
    }
    this._status = 'CHECKED_OUT';
    this.touch(now);
    this._domainEvents.push(
      createDomainEvent(
        'CartCheckedOut',
        this.id,
        this._version,
        { ownerId: this._ownerId, itemCount: this.totalQuantity },
        now,
      ),
    );
  }

  public markExpired(now: Date = new Date()): void {
    if (this._status === 'ACTIVE') {
      this._status = 'EXPIRED';
      this.touch(now);
    }
  }

  public pullDomainEvents(): CartEvent[] {
    const events = [...this._domainEvents];
    this._domainEvents = [];
    return events;
  }

  public toSnapshot(): CartSnapshot {
    return {
      id: this.id,
      ownerId: this._ownerId,
      currency: this.currency,
      status: this._status,
      version: this._version,
      items: Array.from(this._items.values(), (item) => item.toSnapshot()),
      couponCodes: Array.from(this._couponCodes),
      createdAt: this.createdAt.toISOString(),
      updatedAt: this._updatedAt.toISOString(),
      expiresAt: this._expiresAt ? this._expiresAt.toISOString() : null,
      limits: { ...this.limits },
    };
  }
}

import type { Cart } from '../domain/cart.js';
import type { CartItem } from '../domain/cart-item.js';
import { Money } from '../domain/money.js';

export interface AppliedPromotion {
  promotionId: string;
  name: string;
  couponCode?: string;
  discount: Money;
  lineDiscounts: Record<string, Money>;
  description: string;
}

export interface PromotionEvaluationInput {
  cart: Cart;
  remainingSubtotal: Money;
  now: Date;
}

export interface PromotionEvaluationResult {
  applicable: boolean;
  discount: Money;
  lineDiscounts?: Record<string, Money>;
  description: string;
  reason?: string;
}

export interface PromotionRule {
  readonly id: string;
  readonly name: string;
  readonly priority: number;
  readonly stackable: boolean;
  readonly couponCode?: string;
  readonly startsAt?: Date;
  readonly endsAt?: Date;

  isWithinSchedule(now: Date): boolean;
  evaluate(input: PromotionEvaluationInput): PromotionEvaluationResult;
}

export abstract class BasePromotionRule implements PromotionRule {
  public readonly id: string;
  public readonly name: string;
  public readonly priority: number;
  public readonly stackable: boolean;
  public readonly couponCode?: string;
  public readonly startsAt?: Date;
  public readonly endsAt?: Date;

  protected constructor(params: {
    id: string;
    name: string;
    priority?: number;
    stackable?: boolean;
    couponCode?: string;
    startsAt?: Date;
    endsAt?: Date;
  }) {
    this.id = params.id;
    this.name = params.name;
    this.priority = params.priority ?? 100;
    this.stackable = params.stackable ?? true;
    if (params.couponCode !== undefined) {
      this.couponCode = params.couponCode.trim().toUpperCase();
    }
    if (params.startsAt !== undefined) {
      this.startsAt = params.startsAt;
    }
    if (params.endsAt !== undefined) {
      this.endsAt = params.endsAt;
    }
  }

  public isWithinSchedule(now: Date): boolean {
    if (this.startsAt && now.getTime() < this.startsAt.getTime()) return false;
    if (this.endsAt && now.getTime() > this.endsAt.getTime()) return false;
    return true;
  }

  protected matchesItem(
    item: CartItem,
    productIds?: ReadonlyArray<string>,
    categoryIds?: ReadonlyArray<string>,
  ): boolean {
    const productMatch = !productIds || productIds.includes(item.productId);
    const categoryMatch = !categoryIds || categoryIds.includes(item.categoryId);
    return productMatch && categoryMatch;
  }

  public abstract evaluate(input: PromotionEvaluationInput): PromotionEvaluationResult;
}

/**
 * Descuento porcentual sobre el carrito completo o sobre categorías/productos filtrados.
 */
export class PercentageDiscountRule extends BasePromotionRule {
  private readonly percentage: number;
  private readonly minSubtotal?: Money;
  private readonly maxDiscount?: Money;
  private readonly productIds?: ReadonlyArray<string>;
  private readonly categoryIds?: ReadonlyArray<string>;

  constructor(params: {
    id: string;
    name: string;
    percentage: number;
    priority?: number;
    stackable?: boolean;
    couponCode?: string;
    minSubtotal?: Money;
    maxDiscount?: Money;
    productIds?: ReadonlyArray<string>;
    categoryIds?: ReadonlyArray<string>;
    startsAt?: Date;
    endsAt?: Date;
  }) {
    super(params);
    this.percentage = params.percentage;
    if (params.minSubtotal !== undefined) this.minSubtotal = params.minSubtotal;
    if (params.maxDiscount !== undefined) this.maxDiscount = params.maxDiscount;
    if (params.productIds !== undefined) this.productIds = params.productIds;
    if (params.categoryIds !== undefined) this.categoryIds = params.categoryIds;
  }

  public evaluate(input: PromotionEvaluationInput): PromotionEvaluationResult {
    const currency = input.cart.currency;
    if (input.remainingSubtotal.isZero()) {
      return {
        applicable: false,
        discount: Money.zero(currency),
        description: this.name,
        reason: 'El subtotal restante es cero.',
      };
    }

    if (this.minSubtotal) {
      this.minSubtotal.assertSameCurrency(input.remainingSubtotal);
      if (input.cart.subtotal().lessThan(this.minSubtotal)) {
        return {
          applicable: false,
          discount: Money.zero(currency),
          description: this.name,
          reason: `Requiere un subtotal mínimo de ${this.minSubtotal.format()}.`,
        };
      }
    }

    const lineDiscounts: Record<string, Money> = {};
    let eligibleBase = Money.zero(currency);

    for (const item of input.cart.items) {
      if (this.matchesItem(item, this.productIds, this.categoryIds)) {
        eligibleBase = eligibleBase.add(item.subtotal());
      }
    }

    if (eligibleBase.isZero()) {
      return {
        applicable: false,
        discount: Money.zero(currency),
        description: this.name,
        reason: 'No hay artículos elegibles para esta promoción.',
      };
    }

    let rawDiscount = eligibleBase.percentage(this.percentage);
    if (this.maxDiscount) {
      rawDiscount = rawDiscount.min(this.maxDiscount);
    }
    const clampedDiscount = rawDiscount.min(input.remainingSubtotal);

    if (clampedDiscount.isZero()) {
      return {
        applicable: false,
        discount: Money.zero(currency),
        description: this.name,
        reason: 'El descuento calculado es cero.',
      };
    }

    // Distribuimos proporcionalmente por línea elegible
    let distributed = Money.zero(currency);
    const eligibleItems = input.cart.items.filter((item) =>
      this.matchesItem(item, this.productIds, this.categoryIds),
    );
    eligibleItems.forEach((item, index) => {
      if (index === eligibleItems.length - 1) {
        lineDiscounts[item.lineKey] = clampedDiscount.subtractClampedZero(distributed);
      } else {
        const share =
          eligibleBase.amountMinor > 0
            ? Money.fromMinor(
                Math.floor(
                  (clampedDiscount.amountMinor * item.subtotal().amountMinor) /
                    eligibleBase.amountMinor,
                ),
                currency,
              )
            : Money.zero(currency);
        lineDiscounts[item.lineKey] = share;
        distributed = distributed.add(share);
      }
    });

    return {
      applicable: true,
      discount: clampedDiscount,
      lineDiscounts,
      description: `${this.name} (-${this.percentage}%)`,
    };
  }
}

/**
 * Descuento de importe fijo (p. ej. 15 EUR de descuento en compras >= 100 EUR).
 */
export class FixedAmountDiscountRule extends BasePromotionRule {
  private readonly amount: Money;
  private readonly minSubtotal?: Money;

  constructor(params: {
    id: string;
    name: string;
    amount: Money;
    minSubtotal?: Money;
    priority?: number;
    stackable?: boolean;
    couponCode?: string;
    startsAt?: Date;
    endsAt?: Date;
  }) {
    super(params);
    this.amount = params.amount;
    if (params.minSubtotal !== undefined) this.minSubtotal = params.minSubtotal;
  }

  public evaluate(input: PromotionEvaluationInput): PromotionEvaluationResult {
    const currency = input.cart.currency;
    this.amount.assertSameCurrency(input.remainingSubtotal);

    if (input.remainingSubtotal.isZero()) {
      return {
        applicable: false,
        discount: Money.zero(currency),
        description: this.name,
        reason: 'El subtotal restante es cero.',
      };
    }

    if (this.minSubtotal) {
      this.minSubtotal.assertSameCurrency(input.remainingSubtotal);
      if (input.cart.subtotal().lessThan(this.minSubtotal)) {
        return {
          applicable: false,
          discount: Money.zero(currency),
          description: this.name,
          reason: `Requiere un subtotal mínimo de ${this.minSubtotal.format()}.`,
        };
      }
    }

    const discount = this.amount.min(input.remainingSubtotal);
    return {
      applicable: !discount.isZero(),
      discount,
      description: `${this.name} (-${discount.format()})`,
    };
  }
}

/**
 * Promoción tipo 2x1, 3x2 ("Compra X, lleva Y gratis") por cada línea elegible.
 */
export class BuyXGetYRule extends BasePromotionRule {
  private readonly buyQuantity: number;
  private readonly freeQuantity: number;
  private readonly productIds?: ReadonlyArray<string>;
  private readonly categoryIds?: ReadonlyArray<string>;

  constructor(params: {
    id: string;
    name: string;
    buyQuantity: number;
    freeQuantity: number;
    productIds?: ReadonlyArray<string>;
    categoryIds?: ReadonlyArray<string>;
    priority?: number;
    stackable?: boolean;
    couponCode?: string;
    startsAt?: Date;
    endsAt?: Date;
  }) {
    super(params);
    this.buyQuantity = params.buyQuantity;
    this.freeQuantity = params.freeQuantity;
    if (params.productIds !== undefined) this.productIds = params.productIds;
    if (params.categoryIds !== undefined) this.categoryIds = params.categoryIds;
  }

  public evaluate(input: PromotionEvaluationInput): PromotionEvaluationResult {
    const currency = input.cart.currency;
    const bundleSize = this.buyQuantity + this.freeQuantity;
    let totalDiscount = Money.zero(currency);
    const lineDiscounts: Record<string, Money> = {};

    for (const item of input.cart.items) {
      if (!this.matchesItem(item, this.productIds, this.categoryIds)) continue;
      const bundles = Math.floor(item.quantity / bundleSize);
      if (bundles > 0) {
        const freeUnits = bundles * this.freeQuantity;
        const itemDiscount = item.unitPrice.multiply(freeUnits);
        lineDiscounts[item.lineKey] = itemDiscount;
        totalDiscount = totalDiscount.add(itemDiscount);
      }
    }

    const clamped = totalDiscount.min(input.remainingSubtotal);
    if (clamped.isZero()) {
      return {
        applicable: false,
        discount: Money.zero(currency),
        description: this.name,
        reason: `Necesitas al menos ${bundleSize} unidades de un producto elegible.`,
      };
    }

    return {
      applicable: true,
      discount: clamped,
      lineDiscounts,
      description: `${this.name} (${bundleSize}x${this.buyQuantity})`,
    };
  }
}

export interface VolumeTier {
  minQuantity: number;
  percentage: number;
}

/**
 * Descuento escalonado por volumen de unidades (p. ej. >=5 uds -> 10%, >=10 uds -> 20%).
 */
export class TieredVolumeDiscountRule extends BasePromotionRule {
  private readonly tiers: ReadonlyArray<VolumeTier>;
  private readonly productIds?: ReadonlyArray<string>;
  private readonly categoryIds?: ReadonlyArray<string>;

  constructor(params: {
    id: string;
    name: string;
    tiers: ReadonlyArray<VolumeTier>;
    productIds?: ReadonlyArray<string>;
    categoryIds?: ReadonlyArray<string>;
    priority?: number;
    stackable?: boolean;
    couponCode?: string;
    startsAt?: Date;
    endsAt?: Date;
  }) {
    super(params);
    this.tiers = [...params.tiers].sort((a, b) => b.minQuantity - a.minQuantity);
    if (params.productIds !== undefined) this.productIds = params.productIds;
    if (params.categoryIds !== undefined) this.categoryIds = params.categoryIds;
  }

  public evaluate(input: PromotionEvaluationInput): PromotionEvaluationResult {
    const currency = input.cart.currency;
    let eligibleQty = 0;
    let eligibleSubtotal = Money.zero(currency);

    for (const item of input.cart.items) {
      if (this.matchesItem(item, this.productIds, this.categoryIds)) {
        eligibleQty += item.quantity;
        eligibleSubtotal = eligibleSubtotal.add(item.subtotal());
      }
    }

    const matchedTier = this.tiers.find((tier) => eligibleQty >= tier.minQuantity);
    if (!matchedTier || eligibleSubtotal.isZero()) {
      return {
        applicable: false,
        discount: Money.zero(currency),
        description: this.name,
        reason: 'No se alcanzó la cantidad mínima por volumen.',
      };
    }

    const discount = eligibleSubtotal
      .percentage(matchedTier.percentage)
      .min(input.remainingSubtotal);

    return {
      applicable: !discount.isZero(),
      discount,
      description: `${this.name} (${matchedTier.percentage}% por ${eligibleQty} uds.)`,
    };
  }
}

export class PromotionRegistry {
  private readonly rules = new Map<string, PromotionRule>();

  public register(rule: PromotionRule): void {
    this.rules.set(rule.id, rule);
  }

  public unregister(ruleId: string): boolean {
    return this.rules.delete(ruleId);
  }

  public getAll(): PromotionRule[] {
    return Array.from(this.rules.values()).sort((a, b) => a.priority - b.priority);
  }

  public findByCouponCode(code: string): PromotionRule | undefined {
    const normalized = code.trim().toUpperCase();
    for (const rule of this.rules.values()) {
      if (rule.couponCode === normalized) {
        return rule;
      }
    }
    return undefined;
  }

  /**
   * Evalúa promociones automáticas y cupones aplicados al carrito.
   * Si hay promociones no acumulables (stackable=false), selecciona la de mayor beneficio.
   */
  public evaluateCart(cart: Cart, now: Date = new Date()): AppliedPromotion[] {
    const subtotal = cart.subtotal();
    if (subtotal.isZero()) return [];

    const appliedCoupons = new Set(cart.couponCodes);
    const activeRules = this.getAll().filter((rule) => {
      if (!rule.isWithinSchedule(now)) return false;
      if (rule.couponCode) {
        return appliedCoupons.has(rule.couponCode);
      }
      return true;
    });

    const stackableRules = activeRules.filter((r) => r.stackable);
    const exclusiveRules = activeRules.filter((r) => !r.stackable);

    // Evaluamos cuál exclusiva ofrece mayor ahorro sobre el subtotal inicial
    let bestExclusive: { rule: PromotionRule; result: PromotionEvaluationResult } | null = null;
    for (const rule of exclusiveRules) {
      const result = rule.evaluate({ cart, remainingSubtotal: subtotal, now });
      if (result.applicable) {
        if (!bestExclusive || result.discount.greaterThan(bestExclusive.result.discount)) {
          bestExclusive = { rule, result };
        }
      }
    }

    // Evaluamos acumulables secuencialmente para comparar o combinar
    const applied: AppliedPromotion[] = [];
    let remaining = subtotal;

    if (bestExclusive) {
      applied.push({
        promotionId: bestExclusive.rule.id,
        name: bestExclusive.rule.name,
        ...(bestExclusive.rule.couponCode !== undefined
          ? { couponCode: bestExclusive.rule.couponCode }
          : {}),
        discount: bestExclusive.result.discount,
        lineDiscounts: bestExclusive.result.lineDiscounts ?? {},
        description: bestExclusive.result.description,
      });
      remaining = remaining.subtractClampedZero(bestExclusive.result.discount);
    }

    for (const rule of stackableRules) {
      if (remaining.isZero()) break;
      const result = rule.evaluate({ cart, remainingSubtotal: remaining, now });
      if (result.applicable && result.discount.isPositive()) {
        applied.push({
          promotionId: rule.id,
          name: rule.name,
          ...(rule.couponCode !== undefined ? { couponCode: rule.couponCode } : {}),
          discount: result.discount,
          lineDiscounts: result.lineDiscounts ?? {},
          description: result.description,
        });
        remaining = remaining.subtractClampedZero(result.discount);
      }
    }

    return applied;
  }
}

import type { Cart } from '../domain/cart.js';
import type { TaxCategory } from '../domain/cart-item.js';
import { Money } from '../domain/money.js';

export interface TaxBreakdownLine {
  category: TaxCategory;
  ratePercent: number;
  taxableBase: Money;
  taxAmount: Money;
}

export interface TaxCalculationResult {
  totalTax: Money;
  breakdown: TaxBreakdownLine[];
}

export interface TaxStrategy {
  calculate(
    cart: Cart,
    discountedLineTotals: Map<string, Money>,
  ): TaxCalculationResult;
}

/**
 * Estrategia de impuestos por categoría fiscal (p. ej. IVA General 21%, Reducido 10%, Superreducido 4%, Exento 0%).
 */
export class CategoryTaxStrategy implements TaxStrategy {
  private readonly ratesByCategory: Record<TaxCategory, number>;

  constructor(ratesByCategory?: Partial<Record<TaxCategory, number>>) {
    this.ratesByCategory = {
      STANDARD: ratesByCategory?.STANDARD ?? 21,
      REDUCED: ratesByCategory?.REDUCED ?? 10,
      SUPER_REDUCED: ratesByCategory?.SUPER_REDUCED ?? 4,
      EXEMPT: ratesByCategory?.EXEMPT ?? 0,
    };
  }

  public calculate(
    cart: Cart,
    discountedLineTotals: Map<string, Money>,
  ): TaxCalculationResult {
    const baseByCategory = new Map<TaxCategory, Money>();

    for (const item of cart.items) {
      const lineTotal = discountedLineTotals.get(item.lineKey) ?? item.subtotal();
      const prev = baseByCategory.get(item.taxCategory) ?? Money.zero(cart.currency);
      baseByCategory.set(item.taxCategory, prev.add(lineTotal));
    }

    const breakdown: TaxBreakdownLine[] = [];
    let totalTax = Money.zero(cart.currency);

    for (const [category, taxableBase] of baseByCategory.entries()) {
      const ratePercent = this.ratesByCategory[category];
      const taxAmount = taxableBase.percentage(ratePercent);
      breakdown.push({
        category,
        ratePercent,
        taxableBase,
        taxAmount,
      });
      totalTax = totalTax.add(taxAmount);
    }

    return { totalTax, breakdown };
  }
}

/**
 * Estrategia simple sin impuestos (p. ej. B2B intracomunitario con inversión del sujeto pasivo).
 */
export class ZeroTaxStrategy implements TaxStrategy {
  public calculate(cart: Cart): TaxCalculationResult {
    return {
      totalTax: Money.zero(cart.currency),
      breakdown: [],
    };
  }
}

import type { Cart } from '../domain/cart.js';
import { Money } from '../domain/money.js';

export interface ShippingQuote {
  cost: Money;
  methodName: string;
  freeShippingApplied: boolean;
}

export interface ShippingStrategy {
  calculate(cart: Cart, netSubtotalAfterDiscounts: Money): ShippingQuote;
}

/**
 * Tarifa plana con umbral de envío gratuito (p. ej. 5.95 EUR, gratis desde 50 EUR).
 */
export class FreeThresholdShippingStrategy implements ShippingStrategy {
  private readonly flatRate: Money;
  private readonly freeThreshold: Money;
  private readonly methodName: string;

  constructor(params: {
    flatRate: Money;
    freeThreshold: Money;
    methodName?: string;
  }) {
    params.flatRate.assertSameCurrency(params.freeThreshold);
    this.flatRate = params.flatRate;
    this.freeThreshold = params.freeThreshold;
    this.methodName = params.methodName ?? 'Envío estándar';
  }

  public calculate(cart: Cart, netSubtotalAfterDiscounts: Money): ShippingQuote {
    if (cart.isEmpty()) {
      return {
        cost: Money.zero(cart.currency),
        methodName: this.methodName,
        freeShippingApplied: false,
      };
    }

    this.flatRate.assertSameCurrency(netSubtotalAfterDiscounts);

    if (netSubtotalAfterDiscounts.greaterThanOrEqual(this.freeThreshold)) {
      return {
        cost: Money.zero(cart.currency),
        methodName: this.methodName,
        freeShippingApplied: true,
      };
    }

    return {
      cost: this.flatRate,
      methodName: this.methodName,
      freeShippingApplied: false,
    };
  }
}

/**
 * Estrategia de envío calculado por peso total del carrito.
 */
export class WeightBasedShippingStrategy implements ShippingStrategy {
  private readonly baseRate: Money;
  private readonly ratePerKg: Money;
  private readonly methodName: string;

  constructor(params: { baseRate: Money; ratePerKg: Money; methodName?: string }) {
    params.baseRate.assertSameCurrency(params.ratePerKg);
    this.baseRate = params.baseRate;
    this.ratePerKg = params.ratePerKg;
    this.methodName = params.methodName ?? 'Envío por peso';
  }

  public calculate(cart: Cart): ShippingQuote {
    if (cart.isEmpty()) {
      return {
        cost: Money.zero(cart.currency),
        methodName: this.methodName,
        freeShippingApplied: false,
      };
    }

    const totalKg = Math.ceil(cart.totalWeightGrams() / 1000);
    const variableCost = this.ratePerKg.multiply(totalKg);
    return {
      cost: this.baseRate.add(variableCost),
      methodName: this.methodName,
      freeShippingApplied: false,
    };
  }
}

import type { Cart } from '../domain/cart.js';
import { Money } from '../domain/money.js';
import type { AppliedPromotion, PromotionRegistry } from '../promotions/promotion.js';
import type { ShippingQuote, ShippingStrategy } from './shipping-strategy.js';
import type { TaxCalculationResult, TaxStrategy } from './tax-strategy.js';

export interface PricedLineItem {
  lineKey: string;
  productId: string;
  variantId?: string;
  sku: string;
  name: string;
  quantity: number;
  unitPrice: Money;
  grossSubtotal: Money;
  discount: Money;
  netSubtotal: Money;
}

export interface CartPricingSummary {
  cartId: string;
  currency: string;
  version: number;
  lines: PricedLineItem[];
  grossSubtotal: Money;
  totalDiscount: Money;
  netSubtotal: Money;
  appliedPromotions: AppliedPromotion[];
  tax: TaxCalculationResult;
  shipping: ShippingQuote;
  grandTotal: Money;
}

/**
 * Orquesta el pipeline determinista de precios:
 * Subtotal bruto -> Promociones/Descuentos -> Prorrateo por línea -> Impuestos -> Envío -> Total final.
 */
export class PricingEngine {
  private readonly promotionRegistry: PromotionRegistry;
  private readonly taxStrategy: TaxStrategy;
  private readonly shippingStrategy: ShippingStrategy;

  constructor(params: {
    promotionRegistry: PromotionRegistry;
    taxStrategy: TaxStrategy;
    shippingStrategy: ShippingStrategy;
  }) {
    this.promotionRegistry = params.promotionRegistry;
    this.taxStrategy = params.taxStrategy;
    this.shippingStrategy = params.shippingStrategy;
  }

  public calculate(cart: Cart, now: Date = new Date()): CartPricingSummary {
    const currency = cart.currency;
    const grossSubtotal = cart.subtotal();
    const appliedPromotions = this.promotionRegistry.evaluateCart(cart, now);

    let totalDiscount = Money.zero(currency);
    const lineDiscountsAcc = new Map<string, Money>();

    for (const promo of appliedPromotions) {
      totalDiscount = totalDiscount.add(promo.discount);

      // Si la promoción especifica descuentos por línea, los acumulamos;
      // si es global (ej. FixedAmountDiscountRule), prorrateamos por subtotal de línea.
      const hasExplicitLines = Object.keys(promo.lineDiscounts).length > 0;
      if (hasExplicitLines) {
        for (const [lineKey, amount] of Object.entries(promo.lineDiscounts)) {
          const prev = lineDiscountsAcc.get(lineKey) ?? Money.zero(currency);
          lineDiscountsAcc.set(lineKey, prev.add(amount));
        }
      } else if (grossSubtotal.isPositive()) {
        let distributed = Money.zero(currency);
        const items = cart.items;
        items.forEach((item, index) => {
          const share =
            index === items.length - 1
              ? promo.discount.subtractClampedZero(distributed)
              : Money.fromMinor(
                  Math.floor(
                    (promo.discount.amountMinor * item.subtotal().amountMinor) /
                      grossSubtotal.amountMinor,
                  ),
                  currency,
                );
          const prev = lineDiscountsAcc.get(item.lineKey) ?? Money.zero(currency);
          lineDiscountsAcc.set(item.lineKey, prev.add(share));
          distributed = distributed.add(share);
        });
      }
    }

    totalDiscount = totalDiscount.min(grossSubtotal);
    const netSubtotal = grossSubtotal.subtractClampedZero(totalDiscount);

    const discountedLineTotals = new Map<string, Money>();
    const lines: PricedLineItem[] = cart.items.map((item) => {
      const gross = item.subtotal();
      const rawDiscount = lineDiscountsAcc.get(item.lineKey) ?? Money.zero(currency);
      const clampedDiscount = rawDiscount.min(gross);
      const net = gross.subtractClampedZero(clampedDiscount);
      discountedLineTotals.set(item.lineKey, net);

      return {
        lineKey: item.lineKey,
        productId: item.productId,
        ...(item.variantId !== undefined ? { variantId: item.variantId } : {}),
        sku: item.sku,
        name: item.name,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
        grossSubtotal: gross,
        discount: clampedDiscount,
        netSubtotal: net,
      };
    });

    const tax = this.taxStrategy.calculate(cart, discountedLineTotals);
    const shipping = this.shippingStrategy.calculate(cart, netSubtotal);
    const grandTotal = netSubtotal.add(tax.totalTax).add(shipping.cost);

    return {
      cartId: cart.id,
      currency,
      version: cart.version,
      lines,
      grossSubtotal,
      totalDiscount,
      netSubtotal,
      appliedPromotions,
      tax,
      shipping,
      grandTotal,
    };
  }
}

import type { Cart } from '../domain/cart.js';
import type { TaxCategory } from '../domain/cart-item.js';
import type { CartEvent } from '../domain/events.js';
import type { Money } from '../domain/money.js';

export interface CatalogProduct {
  productId: string;
  variantId?: string;
  sku: string;
  name: string;
  categoryId: string;
  taxCategory: TaxCategory;
  unitPrice: Money;
  weightGrams?: number;
  active: boolean;
}

export interface StockReservation {
  sku: string;
  productId: string;
  quantity: number;
}

export interface CartRepository {
  findById(cartId: string): Promise<Cart | null>;
  findActiveByOwner(ownerId: string): Promise<Cart | null>;
  /**
   * Persiste el carrito usando control de concurrencia optimista.
   * @param cart Instancia actual del carrito tras la mutación.
   * @param expectedVersion Versión anterior en almacén (`null` si es creación).
   */
  save(cart: Cart, expectedVersion: number | null): Promise<void>;
  delete(cartId: string): Promise<boolean>;
  purgeExpired(now?: Date): Promise<number>;
}

export interface CatalogPort {
  getProduct(productId: string, variantId?: string): Promise<CatalogProduct | null>;
}

export interface InventoryPort {
  getAvailableStock(sku: string): Promise<number>;
  reserveStock(reservations: ReadonlyArray<StockReservation>): Promise<void>;
  releaseStock(reservations: ReadonlyArray<StockReservation>): Promise<void>;
}

export type CartEventHandler = (event: CartEvent) => void | Promise<void>;

export interface EventBusPort {
  publish(events: ReadonlyArray<CartEvent>): Promise<void>;
  subscribe(handler: CartEventHandler): () => void;
}

export interface IdempotencyStore {
  get<T>(key: string): Promise<T | null>;
  set<T>(key: string, value: T, ttlMs?: number): Promise<void>;
}

import { Cart, type CartSnapshot } from '../domain/cart.js';
import { buildLineKey } from '../domain/cart-item.js';
import {
  ConcurrencyConflictError,
  DomainError,
  InsufficientStockError,
} from '../domain/errors.js';
import type { CartEvent } from '../domain/events.js';
import type {
  CartEventHandler,
  CartRepository,
  CatalogPort,
  CatalogProduct,
  EventBusPort,
  IdempotencyStore,
  InventoryPort,
  StockReservation,
} from '../ports/repositories.js';

/**
 * Repositorio en memoria basado en snapshots inmutables y bloqueo optimista.
 * Simula fielmente el comportamiento de un almacén distribuido (Redis / PostgreSQL).
 */
export class InMemoryCartRepository implements CartRepository {
  private readonly store = new Map<string, CartSnapshot>();

  public async findById(cartId: string): Promise<Cart | null> {
    const snapshot = this.store.get(cartId);
    if (!snapshot) return null;
    return Cart.fromSnapshot(structuredClone(snapshot));
  }

  public async findActiveByOwner(ownerId: string): Promise<Cart | null> {
    const now = new Date();
    for (const snapshot of this.store.values()) {
      if (snapshot.ownerId === ownerId && snapshot.status === 'ACTIVE') {
        const cart = Cart.fromSnapshot(structuredClone(snapshot));
        if (!cart.isExpired(now)) {
          return cart;
        }
      }
    }
    return null;
  }

  public async save(cart: Cart, expectedVersion: number | null): Promise<void> {
    const existing = this.store.get(cart.id);

    if (expectedVersion === null) {
      if (existing) {
        throw new ConcurrencyConflictError(cart.id, 0, existing.version);
      }
    } else {
      if (!existing) {
        throw new DomainError(
          'CART_NOT_FOUND_ON_SAVE',
          `No se puede actualizar el carrito "${cart.id}" porque no existe.`,
        );
      }
      if (existing.version !== expectedVersion) {
        throw new ConcurrencyConflictError(cart.id, expectedVersion, existing.version);
      }
    }

    this.store.set(cart.id, structuredClone(cart.toSnapshot()));
  }

  public async delete(cartId: string): Promise<boolean> {
    return this.store.delete(cartId);
  }

  public async purgeExpired(now: Date = new Date()): Promise<number> {
    let purged = 0;
    for (const [id, snapshot] of this.store.entries()) {
      const cart = Cart.fromSnapshot(snapshot);
      if (cart.isExpired(now)) {
        this.store.delete(id);
        purged += 1;
      }
    }
    return purged;
  }

  public size(): number {
    return this.store.size;
  }
}

export class InMemoryCatalogAdapter implements CatalogPort {
  private readonly products = new Map<string, CatalogProduct>();

  constructor(initialProducts: ReadonlyArray<CatalogProduct> = []) {
    for (const product of initialProducts) {
      this.upsert(product);
    }
  }

  public upsert(product: CatalogProduct): void {
    const key = buildLineKey(product.productId, product.variantId);
    this.products.set(key, product);
  }

  public async getProduct(
    productId: string,
    variantId?: string,
  ): Promise<CatalogProduct | null> {
    const key = buildLineKey(productId, variantId);
    return this.products.get(key) ?? null;
  }
}

export class InMemoryInventoryAdapter implements InventoryPort {
  private readonly stock = new Map<string, number>();

  constructor(initialStock: Record<string, number> = {}) {
    for (const [sku, qty] of Object.entries(initialStock)) {
      this.stock.set(sku, qty);
    }
  }

  public setStock(sku: string, quantity: number): void {
    this.stock.set(sku, Math.max(0, quantity));
  }

  public async getAvailableStock(sku: string): Promise<number> {
    return this.stock.get(sku) ?? 0;
  }

  public async reserveStock(reservations: ReadonlyArray<StockReservation>): Promise<void> {
    // Validación atómica: primero verificamos todos antes de descontar ninguno
    for (const res of reservations) {
      const available = this.stock.get(res.sku) ?? 0;
      if (available < res.quantity) {
        throw new InsufficientStockError(res.productId, res.quantity, available);
      }
    }

    for (const res of reservations) {
      const available = this.stock.get(res.sku) ?? 0;
      this.stock.set(res.sku, available - res.quantity);
    }
  }

  public async releaseStock(reservations: ReadonlyArray<StockReservation>): Promise<void> {
    for (const res of reservations) {
      const available = this.stock.get(res.sku) ?? 0;
      this.stock.set(res.sku, available + res.quantity);
    }
  }
}

export class InMemoryEventBus implements EventBusPort {
  private readonly handlers = new Set<CartEventHandler>();
  public readonly publishedEvents: CartEvent[] = [];

  public async publish(events: ReadonlyArray<CartEvent>): Promise<void> {
    for (const event of events) {
      this.publishedEvents.push(event);
      for (const handler of this.handlers) {
        await handler(event);
      }
    }
  }

  public subscribe(handler: CartEventHandler): () => void {
    this.handlers.add(handler);
    return () => {
      this.handlers.delete(handler);
    };
  }
}

interface StoredIdempotencyEntry<T> {
  value: T;
  expiresAt: number | null;
}

export class InMemoryIdempotencyStore implements IdempotencyStore {
  private readonly entries = new Map<string, StoredIdempotencyEntry<unknown>>();

  public async get<T>(key: string): Promise<T | null> {
    const entry = this.entries.get(key);
    if (!entry) return null;
    if (entry.expiresAt !== null && Date.now() >= entry.expiresAt) {
      this.entries.delete(key);
      return null;
    }
    return structuredClone(entry.value) as T;
  }

  public async set<T>(key: string, value: T, ttlMs = 24 * 60 * 60 * 1000): Promise<void> {
    this.entries.set(key, {
      value: structuredClone(value),
      expiresAt: ttlMs > 0 ? Date.now() + ttlMs : null,
    });
  }
}

import { Cart, type CartLimits } from '../domain/cart.js';
import { buildLineKey } from '../domain/cart-item.js';
import {
